// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount <= address(actor).balance + 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        assertTrue(ok ? c.depositsCount() > 0 : true);
    }
}
